const res = $input.first().json.output;
const msg = Array.isArray(res) && res.length > 0 ? res[0] : null;

if (!msg || !Array.isArray(msg.content) || msg.content.length === 0) {
  return {
    json: {
      has_courses: false,
      reason: "No content array found in OpenAI output",
      courses: [],
      lessons: [],
      raw: $input.first().json,
    },
  };
}

const block = msg.content[0];

if (!block || typeof block.text !== "string") {
  return {
    json: {
      has_courses: false,
      reason: "No text field found in first content block",
      courses: [],
      lessons: [],
      raw: $input.first().json,
    },
  };
}

const text = block.text;

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return {
    json: {
      has_courses: false,
      reason: "Failed to parse JSON from output_text: " + String(e.message || e),
      courses: [],
      lessons: [],
      raw_text: text,
    },
  };
}

// normalize
const courses = Array.isArray(parsed.courses) ? parsed.courses : [];
const lessons = [];

courses.forEach((course, cIdx) => {
  const courseLessons = Array.isArray(course.lessons) ? course.lessons : [];

  courseLessons.forEach((lesson, lIdx) => {

    const fullLesson = {
      ...lesson,
      course_key: course.course_key ?? `course_${cIdx + 1}`,
      course_title: course.course_title ?? "",
      course_description: course.course_description ?? "",
      course_subtitle: course.course_subtitle ?? "",
      course_objective: course.course_objective ?? "",
      course_index: cIdx + 1,
      lesson_key: lesson.lesson_key ?? `course_${cIdx + 1}_lesson_${lIdx + 1}`,
      lesson_index: lIdx + 1,
    };


    fullLesson.topics = Array.isArray(lesson.topics) ? lesson.topics : [];
    fullLesson.quiz = lesson.quiz ?? null;

    lessons.push(fullLesson);
  });
});

return {
  json: {
    has_courses: Boolean(parsed.has_courses),
    reason: parsed.reason || "",
    courses,   
    lessons,  
  },
};

